const src = $json || {};
const body = src.body || {};
const headers = src.headers || {};

const cfg = {
  apiBaseUrl: String(src.apiBaseUrl || 'https://api-app2.simpletexting.com/v2/api').replace(/\/$/, ''),
  simpleTextingApiToken: String(src.simpleTextingApiToken || '').trim(),
  defaultDryRun: !!src.defaultDryRun,
  authHeaderName: String(src.authHeaderName || 'x-lt-webhook-key').toLowerCase(),
  authHeaderValue: String(src.authHeaderValue || ''),
  senderLabel: String(src.senderLabel || 'SimpleTexting').trim(),
  defaultSendMode: String(src.defaultSendMode || 'AUTO').trim().toUpperCase(),
  ghlLocationId: String(src.ghlLocationId || '').trim(),
  ghlApiBaseUrl: String(src.ghlApiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, ''),
  ghlApiKey: String(src.ghlApiKey || '').trim(),
  templateRegistryJson: String(src.templateRegistryJson || '{}').trim(),
  tagStart: String(src.tagStart || 'simpletext_start').trim(),
  tagOngoing: String(src.tagOngoing || 'simpletext_ongoing').trim(),
  tagFinished: String(src.tagFinished || 'simpletext_finished').trim(),
  tagStop: String(src.tagStop || 'simpletext_stop').trim(),
  enforceBusinessHours: !!src.enforceBusinessHours,
  businessTimezone: String(src.businessTimezone || 'Asia/Manila').trim(),
  businessStartHour: Number(src.businessStartHour ?? 9),
  businessEndHour: Number(src.businessEndHour ?? 18),
  businessDaysCsv: String(src.businessDaysCsv || '1,2,3,4,5').trim(),
};

const incomingAuth = headers[cfg.authHeaderName] || headers[cfg.authHeaderName.toLowerCase()] || '';
if (cfg.authHeaderValue && incomingAuth !== cfg.authHeaderValue) {
  return [{ json: { ok: false, error: 'unauthorized', message: 'Invalid webhook auth header' } }];
}

function clean(v) { return String(v || '').trim(); }
function cleanId(v) { return clean(v).replace(/^['

