const src = $json || {};
const body = src.body || {};
const headers = src.headers || {};

const cfg = {
  apiBaseUrl: String(src.apiBaseUrl || 'https://api-app2.simpletexting.com/v2/api').replace(/\/$/, ''),
  simpleTextingApiToken: String(src.simpleTextingApiToken || '').trim(),
  defaultDryRun: !!src.defaultDryRun,
  authHeaderName: String(src.authHeaderName || 'x-lt-webhook-key').toLowerCase(),
  authHeaderValue: String(src.authHeaderValue || ''),
  senderLabel: String(src.senderLabel || 'SimpleTexting').trim(),
  defaultSendMode: String(src.defaultSendMode || 'AUTO').trim().toUpperCase(),
  ghlLocationId: String(src.ghlLocationId || '').trim(),
  ghlApiBaseUrl: String(src.ghlApiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, ''),
  ghlApiKey: String(src.ghlApiKey || '').trim(),
  templateRegistryJson: String(src.templateRegistryJson || '{}').trim(),
  tagStart: String(src.tagStart || 'simpletext_start').trim(),
  tagOngoing: String(src.tagOngoing || 'simpletext_ongoing').trim(),
  tagFinished: String(src.tagFinished || 'simpletext_finished').trim(),
  tagStop: String(src.tagStop || 'simpletext_stop').trim(),
  enforceBusinessHours: !!src.enforceBusinessHours,
  businessTimezone: String(src.businessTimezone || 'Asia/Manila').trim(),
  businessStartHour: Number(src.businessStartHour ?? 9),
  businessEndHour: Number(src.businessEndHour ?? 18),
  businessDaysCsv: String(src.businessDaysCsv || '1,2,3,4,5').trim(),
};

const incomingAuth = headers[cfg.authHeaderName] || headers[cfg.authHeaderName.toLowerCase()] || '';
if (cfg.authHeaderValue && incomingAuth !== cfg.authHeaderValue) {
  return [{ json: { ok: false, error: 'unauthorized', message: 'Invalid webhook auth header' } }];
}

function clean(v) { return String(v || '').trim(); }
function parseBoolean(v, fallback) {
  if (v === undefined || v === null || v === '') return fallback;
  if (typeof v === 'boolean') return v;
  const s = String(v).trim().toLowerCase();
  if (['true', '1', 'yes', 'y'].includes(s)) return true;
  if (['false', '0', 'no', 'n'].includes(s)) return false;
  return fallback;
}
function normalizePhone(v) {
  const digits = clean(v).replace(/\D/g, '');
  if (!digits) return '';
  if (digits.length === 11 && digits.startsWith('1')) return digits.slice(1);
  return digits;
}
function formatPhone(v) {
  const digits = normalizePhone(v);
  if (!digits) return '';
  if (digits.length === 10) return `+1 ${digits.slice(0,3)}-${digits.slice(3,6)}-${digits.slice(6)}`;
  return `+${digits}`;
}
function normalizeTemplateKey(value) {
  return clean(value).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

function normalizeCustomData(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  return Object.fromEntries(Object.entries(value).map(([key, item]) => [String(key).trim().replace(/^['\"]|['\"]$/g, ''), item]));
}

function getBusinessWindowMeta() {
  const tz = cfg.businessTimezone || 'Asia/Manila';
  const now = new Date();
  const fmt = new Intl.DateTimeFormat('en-US', {
    timeZone: tz,
    hour12: false,
    weekday: 'short',
    hour: '2-digit',
    minute: '2-digit',
  });
  const parts = fmt.formatToParts(now);
  const map = Object.fromEntries(parts.map((p) => [p.type, p.value]));
  const weekdayMap = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  const day = weekdayMap[map.weekday] ?? -1;
  const hour = Number(map.hour || 0);
  const minute = Number(map.minute || 0);
  const currentMinutes = hour * 60 + minute;
  const start = Math.max(0, Math.min(23, Number.isFinite(cfg.businessStartHour) ? cfg.businessStartHour : 9));
  const end = Math.max(1, Math.min(24, Number.isFinite(cfg.businessEndHour) ? cfg.businessEndHour : 18));
  const allowedDays = String(cfg.businessDaysCsv || '1,2,3,4,5')
    .split(',')
    .map((s) => Number(String(s).trim()))
    .filter((n) => Number.isInteger(n) && n >= 0 && n <= 6);
  const inDay = allowedDays.includes(day);
  const inHour = currentMinutes >= (start * 60) && currentMinutes < (end * 60);
  return { timezone: tz, day, hour, minute, startHour: start, endHour: end, allowedDays, withinBusinessHours: inDay && inHour };
}

function buildVariableMap(payload) {
  const variables = (payload.variables && typeof payload.variables === 'object' && !Array.isArray(payload.variables)) ? payload.variables : {};
  const contact = (payload.contact && typeof payload.contact === 'object' && !Array.isArray(payload.contact)) ? payload.contact : {};
  const customData = normalizeCustomData(payload.customData);
  const merged = { ...contact, ...customData, ...payload, ...variables };
  delete merged.variables;
  delete merged.contact;
  delete merged.customData;
  return Object.fromEntries(Object.entries(merged).map(([key, value]) => [String(key), value == null ? '' : String(value)]));
}
function applyVariables(template, variableMap) {
  return String(template || '').replace(/{{\s*([^{}]+?)\s*}}/g, (_, key) => {
    const trimmed = String(key || '').trim();
    if (Object.prototype.hasOwnProperty.call(variableMap, trimmed)) return variableMap[trimmed];
    const normalized = trimmed.replace(/\./g, '_');
    if (Object.prototype.hasOwnProperty.call(variableMap, normalized)) return variableMap[normalized];
    return '';
  });
}
function normalizeMediaItems(payload) {
  const raw = [];
  if (Array.isArray(payload.mediaItems)) raw.push(...payload.mediaItems);
  if (Array.isArray(payload.mediaUrls)) raw.push(...payload.mediaUrls);
  if (Array.isArray(payload.mediaIds)) raw.push(...payload.mediaIds);
  if (payload.mediaUrl) raw.push(payload.mediaUrl);
  return raw.map((item) => clean(item)).filter(Boolean);
}
function normalizeTagList(value) {
  if (Array.isArray(value)) return value.map((item) => clean(typeof item === 'string' ? item : item?.name || item?.value)).filter(Boolean);
  if (typeof value === 'string') return value.split(',').map((item) => clean(item)).filter(Boolean);
  return [];
}
function extractContactTagNames(contact) {
  return normalizeTagList(contact?.tags || []);
}
function getContactsArray(data) {
  if (Array.isArray(data?.contacts)) return data.contacts;
  if (Array.isArray(data?.data?.contacts)) return data.data.contacts;
  return [];
}
function getSingleContact(data) {
  if (data?.contact && typeof data.contact === 'object') return data.contact;
  if (data?.data?.contact && typeof data.data.contact === 'object') return data.data.contact;
  if (data && typeof data === 'object' && data.id) return data;
  return null;
}

let templateRegistry = {};
try {
  templateRegistry = JSON.parse(cfg.templateRegistryJson || '{}');
} catch {
  return [{ json: { ok: false, error: 'invalid_template_registry', message: 'templateRegistryJson is not valid JSON' } }];
}

const templateAliases = {};
for (const [key, value] of Object.entries(templateRegistry)) {
  templateAliases[normalizeTemplateKey(key)] = key;
  const name = clean(value && typeof value === 'object' ? value.name : '');
  if (name) templateAliases[normalizeTemplateKey(name)] = key;
}

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}
async function apiRequest({ method, url, headers, body }) {
  const options = { method, url, headers, json: true };
  if (body !== undefined) options.body = body;
  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, data };
  } catch (err) {
    return {
      ok: false,
      status: err?.statusCode || err?.httpCode || err?.cause?.statusCode || 500,
      data: err?.response?.body || err?.message || err,
    };
  }
}
async function fetchContactById(contactId) {
  if (!contactId || !cfg.ghlApiKey) return null;
  const res = await apiRequest.call(this, {
    method: 'GET',
    url: `${cfg.ghlApiBaseUrl}/contacts/${encodeURIComponent(contactId)}`,
    headers: {
      Authorization: `Bearer ${cfg.ghlApiKey}`,
      Version: '2021-07-28',
      Accept: 'application/json',
    },
  });
  if (!res.ok) return null;
  return getSingleContact(res.data);
}
async function searchContactByPhone(phone) {
  if (!phone || !cfg.ghlApiKey || !cfg.ghlLocationId) return null;
  const lookup = await apiRequest.call(this, {
    method: 'GET',
    url: `${cfg.ghlApiBaseUrl}/contacts/?locationId=${encodeURIComponent(cfg.ghlLocationId)}&query=${encodeURIComponent(phone)}&limit=10`,
    headers: {
      Authorization: `Bearer ${cfg.ghlApiKey}`,
      Version: '2021-07-28',
      Accept: 'application/json',
    },
  });
  if (!lookup.ok) return { lookupFailed: true, details: lookup.data };
  const match = getContactsArray(lookup.data).find((contact) => normalizePhone(contact?.phone) === phone);
  return match || null;
}
async function resolveGhlContact(requestedContactId, phone) {
  if (requestedContactId) {
    const contact = await fetchContactById.call(this, requestedContactId);
    return { contactId: requestedContactId, resolvedVia: 'input_contactId', contact };
  }
  if (!cfg.ghlApiKey || !cfg.ghlLocationId || !phone) return { contactId: '', resolvedVia: 'unavailable', contact: null };
  const searched = await searchContactByPhone.call(this, phone);
  if (!searched) return { contactId: '', resolvedVia: 'phone_lookup_no_match', contact: null };
  if (searched.lookupFailed) return { contactId: '', resolvedVia: 'lookup_failed', contact: null, details: searched.details };
  return { contactId: searched.id || '', resolvedVia: 'phone_lookup', contact: searched };
}
async function createGhlNote(contactId, noteBody) {
  return await apiRequest.call(this, {
    method: 'POST',
    url: `${cfg.ghlApiBaseUrl}/contacts/${encodeURIComponent(contactId)}/notes`,
    headers: {
      Authorization: `Bearer ${cfg.ghlApiKey}`,
      Version: '2021-07-28',
      Accept: 'application/json',
      'Content-Type': 'application/json',
    },
    body: { body: noteBody },
  });
}
async function addTags(contactId, tags) {
  const normalized = normalizeTagList(tags);
  if (!contactId || !normalized.length) return { attempted: false, ok: true, tags: normalized };
  return await apiRequest.call(this, {
    method: 'POST',
    url: `${cfg.ghlApiBaseUrl}/contacts/${encodeURIComponent(contactId)}/tags`,
    headers: {
      Authorization: `Bearer ${cfg.ghlApiKey}`,
      Version: '2021-07-28',
      Accept: 'application/json',
      'Content-Type': 'application/json',
    },
    body: { tags: normalized },
  });
}
async function removeTags(contactId, tags) {
  const normalized = normalizeTagList(tags);
  if (!contactId || !normalized.length) return { attempted: false, ok: true, tags: normalized };
  return await apiRequest.call(this, {
    method: 'DELETE',
    url: `${cfg.ghlApiBaseUrl}/contacts/${encodeURIComponent(contactId)}/tags`,
    headers: {
      Authorization: `Bearer ${cfg.ghlApiKey}`,
      Version: '2021-07-28',
      Accept: 'application/json',
      'Content-Type': 'application/json',
    },
    body: { tags: normalized },
  });
}

const validModes = new Set(['AUTO', 'SINGLE_SMS_STRICTLY', 'MMS_PREFERRED']);
const dryRun = parseBoolean(body.dryRun, cfg.defaultDryRun);
const requestedContactId = clean(body.contactId || customData.contactId || body.ghlContactId);
const contactPhone = normalizePhone(body.contactPhone || customData.contactPhone || body.to || body.phone || body.mobile || body.destination);
const accountPhone = normalizePhone(body.accountPhone || customData.accountPhone || body.from || body.senderPhone || body.fromNumber);
const rawMessage = clean(body.text || customData.text || body.message || customData.message || body.smsBody || customData.smsBody);
const templateKeyInput = clean(body.templateKey || customData.templateKey || body.snippetKey || body.template || body.smsTemplateKey);
const resolvedTemplateKey = templateKeyInput ? (templateAliases[normalizeTemplateKey(templateKeyInput)] || '') : '';
const templateEntry = resolvedTemplateKey ? templateRegistry[resolvedTemplateKey] : null;
const variableMap = buildVariableMap(body);
const templateMessage = templateEntry ? applyVariables(templateEntry.message || '', variableMap).trim() : '';
const text = rawMessage || templateMessage;
const subject = clean(body.subject);
const fallbackText = clean(body.fallbackText || body.mmsFallbackText);
const mediaItems = normalizeMediaItems(body);
const requestedMode = clean(body.mode).toUpperCase();
const mode = validModes.has(requestedMode)
  ? requestedMode
  : (mediaItems.length > 0 ? 'MMS_PREFERRED' : (validModes.has(cfg.defaultSendMode) ? cfg.defaultSendMode : 'AUTO'));
const campaignKey = clean(body.campaignKey || body.sequenceKey || body.workflowKey);
const externalId = clean(body.externalId || body.messageKey || body.eventId);
const senderLabel = clean(body.senderLabel || cfg.senderLabel);
const templateName = clean(templateEntry && typeof templateEntry === 'object' ? templateEntry.name : '');
const addTagsInput = normalizeTagList(body.addTags);
const removeTagsInput = normalizeTagList(body.removeTags);

if (!contactPhone) return [{ json: { ok: false, error: 'missing_phone', message: 'Provide contactPhone/to/phone/mobile/destination' } }];
if (contactPhone.length !== 10) return [{ json: { ok: false, error: 'invalid_phone', message: 'SimpleTexting v2 expects a 10-digit contactPhone', contactPhone } }];
if (accountPhone && accountPhone.length !== 10) return [{ json: { ok: false, error: 'invalid_account_phone', message: 'SimpleTexting v2 expects a 10-digit accountPhone', accountPhone } }];
if (!text) return [{ json: { ok: false, error: 'missing_text', message: 'Provide text/message/smsBody or a valid templateKey' } }];
const businessWindow = getBusinessWindowMeta();
if (cfg.enforceBusinessHours && !businessWindow.withinBusinessHours) {
  return [{ json: {
    ok: false,
    dryRun,
    error: 'outside_business_hours',
    message: 'SMS blocked: outside configured business hours',
    businessWindow,
    templateKey: resolvedTemplateKey || templateKeyInput || '',
    contactPhone,
  } }];
}
if (templateKeyInput && !templateEntry && !rawMessage) {
  return [{ json: { ok: false, error: 'unknown_template_key', message: 'Unknown templateKey', templateKey: templateKeyInput, availableTemplateKeys: Object.keys(templateRegistry) } }];
}
if (mediaItems.length > 0 && mode === 'SINGLE_SMS_STRICTLY') {
  return [{ json: { ok: false, error: 'invalid_mode_for_media', message: 'SINGLE_SMS_STRICTLY cannot be used with mediaItems', mode } }];
}

const requestBody = { contactPhone, mode, text };
if (accountPhone) requestBody.accountPhone = accountPhone;
if (subject) requestBody.subject = subject;
if (fallbackText) requestBody.fallbackText = fallbackText;
if (mediaItems.length > 0) requestBody.mediaItems = mediaItems;

const resolvedContact = await resolveGhlContact.call(this, requestedContactId, contactPhone);
const existingTagNames = extractContactTagNames(resolvedContact.contact);
const isStopped = existingTagNames.includes(cfg.tagStop);
if (isStopped) {
  return [{ json: {
    ok: false,
    dryRun,
    error: 'contact_opted_out',
    message: 'Contact is suppressed by simpletext_stop tag',
    contactPhone,
    ghlContactResolution: { contactId: resolvedContact.contactId, resolvedVia: resolvedContact.resolvedVia, existingTags: existingTagNames },
  } }];
}

const notePreview = [
  'SMS sent via SimpleTexting',
  `To: ${formatPhone(contactPhone) || contactPhone}`,
  accountPhone ? `From: ${formatPhone(accountPhone) || accountPhone}` : '',
  templateName ? `Template: ${templateName}` : '',
  campaignKey ? `Campaign Key: ${campaignKey}` : '',
  'Message:',
  text,
].filter(Boolean).join('\n');

if (dryRun) {
  return [{ json: {
    ok: true,
    dryRun: true,
    action: 'would_send_message',
    provider: 'SimpleTexting',
    endpoint: 'messages',
    requestBody,
    campaignKey,
    externalId,
    senderLabel,
    templateKey: resolvedTemplateKey || templateKeyInput || '',
    templateName,
    textLength: text.length,
    ghlNotePreview: notePreview,
    ghlContactResolution: { contactId: resolvedContact.contactId, resolvedVia: resolvedContact.resolvedVia, existingTags: existingTagNames },
    requestedTagAdds: addTagsInput,
    requestedTagRemovals: removeTagsInput,
  } }];
}

if (!cfg.simpleTextingApiToken) return [{ json: { ok: false, error: 'missing_api_token', message: 'Missing SimpleTexting API token in workflow config' } }];

const sendRes = await apiRequest.call(this, {
  method: 'POST',
  url: `${cfg.apiBaseUrl}/messages`,
  headers: {
    Authorization: `Bearer ${cfg.simpleTextingApiToken}`,
    Accept: 'application/json',
    'Content-Type': 'application/json',
  },
  body: requestBody,
});
if (!sendRes.ok) {
  return [{ json: {
    ok: false,
    dryRun: false,
    error: 'simpletexting_send_failed',
    endpoint: 'messages',
    contactPhone,
    accountPhone,
    campaignKey,
    externalId,
    senderLabel,
    templateKey: resolvedTemplateKey || templateKeyInput || '',
    templateName,
    details: sendRes.data,
    statusCode: sendRes.status,
  } }];
}

const providerResponse = sendRes.data || {};
const providerMessageId = clean(providerResponse.id);
const sentAt = new Date().toISOString();
const noteBody = [
  'SMS sent via SimpleTexting',
  `Sent At: ${sentAt}`,
  `To: ${formatPhone(contactPhone) || contactPhone}`,
  accountPhone ? `From: ${formatPhone(accountPhone) || accountPhone}` : '',
  providerMessageId ? `Provider Message ID: ${providerMessageId}` : '',
  templateName ? `Template: ${templateName}` : '',
  campaignKey ? `Campaign Key: ${campaignKey}` : '',
  'Message:',
  text,
].filter(Boolean).join('\n');

let noteSync = { attempted: false, contactId: resolvedContact.contactId || '', resolvedVia: resolvedContact.resolvedVia || '', ok: false };
if (cfg.ghlApiKey && cfg.ghlLocationId && resolvedContact.contactId) {
  const noteRes = await createGhlNote.call(this, resolvedContact.contactId, noteBody);
  noteSync.attempted = true;
  noteSync.ok = noteRes.ok;
  noteSync.details = noteRes.ok ? (noteRes.data?.note || noteRes.data || {}) : noteRes.data;
}

let tagSync = { attempted: false, contactId: resolvedContact.contactId || '', added: addTagsInput, removed: removeTagsInput, addOk: false, removeOk: false };
if (cfg.ghlApiKey && cfg.ghlLocationId && resolvedContact.contactId && (addTagsInput.length || removeTagsInput.length)) {
  tagSync.attempted = true;
  if (addTagsInput.length) {
    const addRes = await addTags.call(this, resolvedContact.contactId, addTagsInput);
    tagSync.addOk = !!addRes.ok;
    tagSync.addDetails = addRes.ok ? (addRes.data?.contact || addRes.data || {}) : addRes.data;
  }
  if (removeTagsInput.length) {
    const removeRes = await removeTags.call(this, resolvedContact.contactId, removeTagsInput);
    tagSync.removeOk = !!removeRes.ok;
    tagSync.removeDetails = removeRes.ok ? (removeRes.data?.contact || removeRes.data || {}) : removeRes.data;
  }
}

return [{ json: {
  ok: true,
  dryRun: false,
  action: 'message_sent',
  provider: 'SimpleTexting',
  endpoint: 'messages',
  contactPhone,
  accountPhone,
  campaignKey,
  externalId,
  senderLabel,
  templateKey: resolvedTemplateKey || templateKeyInput || '',
  templateName,
  textLength: text.length,
  mediaItems,
  providerResponse,
  providerMessageId,
  ghlNoteSync: noteSync,
  ghlTagSync: tagSync,
} }];
